import { createRequire } from 'module'
const require = createRequire('D:/repository/苏住房G/package.json')
const LIB = 'D:/repository/苏住房G/e2e/std-evaluation/lib/std-eval-lib.cjs'
const { createSuite } = require(LIB)
const suite = createSuite({ name: 'shot2-6582', task: 'verify', dir: 'shot2-6582' })
suite.run(async ({ page, ui, step, note }) => {
  const p = await page()
  await ui.login(p)
  const base = (process.env.E2E_BASE_URL || 'http://127.0.0.1:8101').replace(/\/$/, '')
  await step('home', async () => {
    await p.goto(`${base}/#/index`, { waitUntil: 'domcontentloaded' })
    await p.waitForTimeout(8000)
    // 读取图标 wrap 实际尺寸与 box 高度
    const metrics = await p.evaluate(() => {
      const w = document.querySelector('.kd__icon-wrap')
      const i = document.querySelector('.kd__icon')
      const b = document.querySelector('.kd__box')
      const r = (el) => el ? { w: el.getBoundingClientRect().width, h: el.getBoundingClientRect().height } : null
      return { wrap: r(w), icon: r(i), box: r(b) }
    })
    console.log('METRICS:', JSON.stringify(metrics))
    await p.screenshot({ path: 'e2e/artifacts/fix-6582/home-8101-now.png', fullPage: true }).catch(e=>console.log('fail',e.message))
  })
  note('done')
})

